// Entitlement gate · record a purchase from your checkout's webhook.
// 1) Checks a shared token header. 2) Maps the payload to the purchases columns.
const crypto = require('crypto');

// ---- Settings --------------------------------------------------------------
// Set a long random value here and send it from your checkout as the header x-webhook-token.
// If your checkout signs payloads (HMAC), verify that signature here instead.
const WEBHOOK_TOKEN = 'replace-with-a-long-random-value';
const FOLD_GMAIL_ALIASES = true; // must match the gate
// Map your checkout's statuses to: paid | refunded | disputed | cancelled | pending
const STATUS_MAP = { paid: 'paid', succeeded: 'paid', complete: 'paid', completed: 'paid', active: 'active',
  refunded: 'refunded', refund: 'refunded', chargeback: 'disputed', disputed: 'disputed',
  canceled: 'cancelled', cancelled: 'cancelled', pending: 'pending' };
// ---------------------------------------------------------------------------

const hook = $('Checkout webhook').first().json || {};
const hdr = hook.headers || {};
let b = hook.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
if (!b || typeof b !== 'object') b = {};

const sent = Buffer.from(String(hdr['x-webhook-token'] || ''));
const want = Buffer.from(WEBHOOK_TOKEN);
const tokenOk = WEBHOOK_TOKEN !== 'replace-with-a-long-random-value' && sent.length === want.length && crypto.timingSafeEqual(sent, want);
if (!tokenOk) return [{ json: { ok: false } }];

const s = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const get = (o, path) => path.split('.').reduce((a, k) => (a && a[k] !== undefined ? a[k] : undefined), o);
const first = (...paths) => { for (const p of paths) { const v = get(b, p); if (v !== undefined && v !== null && s(v) !== '') return s(v); } return ''; };

// Common field locations. Add yours if your checkout uses different names.
let email = first('email', 'customer.email', 'customer_email', 'data.object.customer_details.email', 'contact.email', 'buyer.email').toLowerCase();
const at = email.lastIndexOf('@');
if (at > 0) {
  let local = email.slice(0, at), domain = email.slice(at + 1);
  if (domain === 'googlemail.com') domain = 'gmail.com';
  if (FOLD_GMAIL_ALIASES && domain === 'gmail.com') local = local.split('+')[0].replace(/\./g, '');
  email = local + '@' + domain;
}
const sku = first('sku', 'product.sku', 'product_id', 'line_items.0.sku', 'data.object.metadata.sku', 'product.id').toLowerCase();
const orderId = first('order_id', 'id', 'order.id', 'data.object.id', 'transaction_id');
const rawStatus = first('status', 'payment_status', 'financial_status', 'data.object.payment_status', 'event').toLowerCase();
const status = STATUS_MAP[rawStatus] || 'pending';
const purchasedAt = first('purchased_at', 'created_at', 'order.created_at') || new Date().toISOString();
const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) && !!orderId;
return [{ json: { ok: valid, email, sku, order_id: orderId, status, purchased_at: purchasedAt } }];
